insert into public.topics (id, slug, title, question, summary, status, created_by, created_at) values
  ('topic_congestion_pricing', 'congestion-pricing', 'Congestion Pricing', 'Should cities implement congestion pricing for cars?', 'A policy debate about charging vehicles to enter busy urban areas — weighing congestion relief, transit funding, and environmental gains against fairness, affordability, and trust in institutions.', 'draft', null, '2026-06-09T00:00:00Z');
insert into public.debate_revisions (id, topic_id, revision_number, status, review_status, generated_by, created_by, created_at) values
  ('cp_rev_001', 'topic_congestion_pricing', 1, 'draft', 'unreviewed', 'human', null, '2026-06-09T00:00:00Z');
insert into public.positions (id, revision_id, topic_id, title, short_summary, steelman, status, generated_by, review_status, sort_order) values
  ('cp_pos_a', 'cp_rev_001', 'topic_congestion_pricing', 'Yes — price the zone, invest in transit', 'Implement congestion pricing and direct the revenue to public transport.', 'Cities should charge drivers to enter the most congested zones because scarce road space is currently underpriced. Pricing can reduce traffic, improve travel reliability, reduce pollution, and create a dedicated funding stream for public transport. Fairness concerns are real, but they can be mitigated through transit investment, exemptions, credits, and careful policy design.', 'published', 'human', 'unreviewed', 1),
  ('cp_pos_b', 'cp_rev_001', 'topic_congestion_pricing', 'No — the burden falls unfairly', 'Congestion pricing charges access to public roads and shifts burdens onto those least able to adapt.', 'Congestion pricing charges people for access to public roads and may hurt people who cannot easily change route, schedule, job location, or transport mode. It can also create geographic unfairness, traffic diversion, delivery cost increases, and new administrative complexity. The fact that pricing can reduce congestion does not prove that its burdens are fairly distributed.', 'published', 'human', 'unreviewed', 2),
  ('cp_pos_c', 'cp_rev_001', 'topic_congestion_pricing', 'Yes, but — only with equity protections', 'Price congestion only with rebates, transparent revenue use, and independent review built in from the start.', 'Congestion pricing can be justified, but only if the city designs it around equity from the start. The policy should include clear exemptions or rebates, transparent revenue use, public reporting, review of traffic diversion, and measurable transit improvements. The goal should be lower congestion and fairer mobility, not just revenue extraction.', 'published', 'human', 'unreviewed', 3);
insert into public.claims (id, revision_id, topic_id, text, claim_type, generated_by, review_status, sort_order) values
  ('cp_c1', 'cp_rev_001', 'topic_congestion_pricing', 'Congestion pricing can reduce vehicle traffic in a priced zone.', array['causal']::text[], 'human', 'unreviewed', 1),
  ('cp_c2', 'cp_rev_001', 'topic_congestion_pricing', 'Congestion pricing can generate revenue for public transit.', array['causal', 'factual']::text[], 'human', 'unreviewed', 2),
  ('cp_c3', 'cp_rev_001', 'topic_congestion_pricing', 'If revenue funds transit, many non-driving residents can benefit.', array['causal']::text[], 'human', 'unreviewed', 3),
  ('cp_c4', 'cp_rev_001', 'topic_congestion_pricing', 'Congestion pricing can create income and geographic equity concerns.', array['factual']::text[], 'human', 'unreviewed', 4),
  ('cp_c5', 'cp_rev_001', 'topic_congestion_pricing', 'Low-income drivers with limited alternatives may be burdened.', array['causal']::text[], 'human', 'unreviewed', 5),
  ('cp_c6', 'cp_rev_001', 'topic_congestion_pricing', 'Benefits and costs depend heavily on revenue use and policy design.', array['causal']::text[], 'human', 'unreviewed', 6),
  ('cp_c7', 'cp_rev_001', 'topic_congestion_pricing', 'Rebates or revenue recycling can change the fairness of congestion pricing.', array['causal']::text[], 'human', 'unreviewed', 7),
  ('cp_c8', 'cp_rev_001', 'topic_congestion_pricing', 'Official program claims should be audited independently over time.', array['normative']::text[], 'human', 'unreviewed', 8),
  ('cp_c9', 'cp_rev_001', 'topic_congestion_pricing', 'Charging for entry to public roads is a fair way to allocate scarce road space.', array['normative']::text[], 'human', 'unreviewed', 9),
  ('cp_c10', 'cp_rev_001', 'topic_congestion_pricing', 'It is unacceptable to impose a new daily cost on drivers who have no realistic alternative.', array['normative']::text[], 'human', 'unreviewed', 10),
  ('cp_c11', 'cp_rev_001', 'topic_congestion_pricing', 'Priced cordons have been associated with measurable reductions in local air pollutants.', array['factual', 'causal']::text[], 'human', 'unreviewed', 11),
  ('cp_c12', 'cp_rev_001', 'topic_congestion_pricing', 'Clear, predictable pricing rules improve public compliance and reduce enforcement disputes.', array['causal']::text[], 'human', 'unreviewed', 12),
  ('cp_c13', 'cp_rev_001', 'topic_congestion_pricing', 'Whether the policy is legitimate depends on transparent, independently audited revenue use.', array['normative']::text[], 'human', 'unreviewed', 13);
insert into public.debate_arguments (id, revision_id, position_id, direction, summary, claim_ids, generated_by, review_status, sort_order) values
  ('cp_arg_a1', 'cp_rev_001', 'cp_pos_a', 'supports', 'Pricing demonstrably reduces traffic in priced zones.', array['cp_c1']::text[], 'human', 'unreviewed', 1),
  ('cp_arg_a2', 'cp_rev_001', 'cp_pos_a', 'supports', 'Tolls create a dedicated, recurring funding stream for transit.', array['cp_c2', 'cp_c3']::text[], 'human', 'unreviewed', 2),
  ('cp_arg_a3', 'cp_rev_001', 'cp_pos_a', 'qualifies', 'Fairness objections are addressable through design, not reasons to abandon the policy.', array['cp_c6']::text[], 'human', 'unreviewed', 3),
  ('cp_arg_b1', 'cp_rev_001', 'cp_pos_b', 'supports', 'The policy raises real income and geographic equity concerns.', array['cp_c4']::text[], 'human', 'unreviewed', 4),
  ('cp_arg_b2', 'cp_rev_001', 'cp_pos_b', 'supports', 'Drivers with no realistic alternative bear the cost without the benefit.', array['cp_c5']::text[], 'human', 'unreviewed', 5),
  ('cp_arg_b3', 'cp_rev_001', 'cp_pos_b', 'qualifies', 'Reduced congestion does not prove the burdens are fairly distributed.', array['cp_c6']::text[], 'human', 'unreviewed', 6),
  ('cp_arg_c1', 'cp_rev_001', 'cp_pos_c', 'supports', 'Rebates and revenue recycling can change the fairness outcome.', array['cp_c7']::text[], 'human', 'unreviewed', 7),
  ('cp_arg_c2', 'cp_rev_001', 'cp_pos_c', 'supports', 'Outcomes hinge on revenue use and policy design, so design for equity explicitly.', array['cp_c6']::text[], 'human', 'unreviewed', 8),
  ('cp_arg_c3', 'cp_rev_001', 'cp_pos_c', 'supports', 'Official program claims need independent auditing over time.', array['cp_c8', 'cp_c13']::text[], 'human', 'unreviewed', 9),
  ('cp_arg_a4', 'cp_rev_001', 'cp_pos_a', 'supports', 'Pricing also clears the air and rests on a fair principle: scarce road space should carry a price.', array['cp_c11', 'cp_c12', 'cp_c9']::text[], 'human', 'unreviewed', 10),
  ('cp_arg_b4', 'cp_rev_001', 'cp_pos_b', 'supports', 'A new daily cost is unacceptable when the driver has no realistic alternative.', array['cp_c10']::text[], 'human', 'unreviewed', 11),
  ('cp_arg_c4', 'cp_rev_001', 'cp_pos_c', 'supports', 'The same air-quality and compliance gains hold here too — provided the design is clear and predictable.', array['cp_c11', 'cp_c12']::text[], 'human', 'unreviewed', 12);
