  ('cp_s3', 'cp_rev_001', 'topic_congestion_pricing', 'https://www.mta.info/fares-tolls/tolls/congestion-relief-zone/about', 'Congestion Relief Zone Toll Information', 'MTA (New York)', 'report', 'found', '2026-06-09', 'Official source for toll design (rates, periods, credits, phase-in through 2031). Not neutral for policy evaluation.', null, 3),
  ('cp_s4', 'cp_rev_001', 'topic_congestion_pricing', 'https://tfl.gov.uk/modes/driving/congestion-charge', 'Congestion Charge', 'Transport for London', 'report', 'found', '2026-06-09', 'Official source for current London charge amount, hours, exemptions, and discounts.', null, 4),
  ('cp_s5', 'cp_rev_001', 'topic_congestion_pricing', 'https://www.itskrs.its.dot.gov/2007-b00333', 'Congestion pricing in London decreases inner city traffic by about 20 percent and generates more than £97 million each year for transit improvements.', 'U.S. DOT ITS Knowledge Resources', 'report', 'found', '2026-06-09', 'Official U.S. DOT ITS entry, identifier 2007-B00333. It summarizes TfL monitoring reports and should be backed by the original reports before production use.', null, 5),
  ('cp_s6', 'cp_rev_001', 'topic_congestion_pricing', 'https://www.gao.gov/products/gao-12-119', 'Road Pricing Can Help Reduce Congestion, but Equity Concerns May Grow', 'U.S. Government Accountability Office', 'report', 'found', '2026-06-09', 'Official U.S. oversight source, report GAO-12-119. Covers U.S. road pricing broadly, not only cordon pricing.', null, 6),
  ('cp_s7', 'cp_rev_001', 'topic_congestion_pricing', 'https://www.cssny.org/news/entry/congestion-pricing-outer-borough-new-yorkers-poverty-data-analysis', 'Congestion Pricing and Outer-Borough New Yorkers in Poverty', 'Community Service Society of New York', 'article', 'found', '2026-06-09', 'Advocacy / policy analysis — not neutral. Useful as a position source, not as final authority.', null, 7),
  ('cp_s8', 'cp_rev_001', 'topic_congestion_pricing', 'https://ucits.org/research_products/policy-brief-congestion-pricing-can-be-equitable-if-a-portion-of-the-revenue-is-returned-to-drivers/', 'Congestion Pricing Can Be Equitable if Revenue Is Returned to Drivers', 'UC Institute of Transportation Studies', 'paper', 'found', '2026-06-09', 'Research institution policy brief. Core source for the rebates / revenue-recycling position.', null, 8);
