insert into public.debate_values (id, revision_id, topic_id, name, description, tension_with, sort_order) values
  ('cp_val_mobility', 'cp_rev_001', 'topic_congestion_pricing', 'Efficient Mobility', 'Scarce road space should be used where it creates the most value; congestion is a cost everyone pays.', array['affordability', 'unrestricted road access']::text[], 1),
  ('cp_val_fairness', 'cp_rev_001', 'topic_congestion_pricing', 'Fairness', 'Public policy should not place its burdens on those least able to adapt or pay.', array['simplicity', 'revenue maximization', 'fast rollout']::text[], 2),
  ('cp_val_environment', 'cp_rev_001', 'topic_congestion_pricing', 'Environmental Protection', 'Fewer vehicle trips mean cleaner air, less noise, and more livable streets.', array['driver convenience', 'short-term household or business costs']::text[], 3),
  ('cp_val_trust', 'cp_rev_001', 'topic_congestion_pricing', 'Institutional Trust', 'Programs that charge the public must report transparently and accept independent evaluation.', array['opaque revenue allocation', 'official self-reporting without independent evaluation']::text[], 4),
  ('cp_val_access', 'cp_rev_001', 'topic_congestion_pricing', 'Unrestricted Road Access', 'Public roads are a shared resource everyone has already paid for; charging a daily fee to enter them is itself a burden.', array['efficient mobility', 'revenue maximization', 'pricing scarce road space']::text[], 5);
