insert into public.tradeoffs (id, revision_id, topic_id, position_id, gain, cost, risk, review_status) values
  ('cp_to_a', 'cp_rev_001', 'topic_congestion_pricing', 'cp_pos_a', 'Less congestion, more transit funding, cleaner air, better travel reliability.', 'Direct fees for some drivers, administrative complexity, political resistance.', 'Poorly designed exemptions or revenue rules could weaken the policy.', 'unreviewed'),
  ('cp_to_b', 'cp_rev_001', 'topic_congestion_pricing', 'cp_pos_b', 'Avoids new fees and avoids burdening constrained drivers.', 'Preserves congestion and may leave transit underfunded.', 'Rejects a tool that could improve citywide mobility if designed well.', 'unreviewed'),
  ('cp_to_c', 'cp_rev_001', 'topic_congestion_pricing', 'cp_pos_c', 'Keeps congestion-reduction benefits while addressing unfair burdens.', 'Slower rollout, more complexity, lower net revenue.', 'Too many carveouts can undermine congestion reduction.', 'unreviewed');
