insert into public.topics (id, slug, title, question, summary, status, created_by, created_at) values
  ('topic_smartphones_schools', 'smartphones-schools', 'Smartphones in Schools', 'Should schools ban smartphones during class?', 'A policy debate about whether schools should ban smartphones during class — weighing attention, learning outcomes, and an equal classroom against student autonomy, digital literacy, family contact, and the real costs of enforcement.', 'draft', null, '2026-04-28T00:00:00Z');
insert into public.debate_revisions (id, topic_id, revision_number, status, review_status, generated_by, created_by, created_at) values
  ('sm_rev_001', 'topic_smartphones_schools', 1, 'draft', 'unreviewed', 'human', null, '2026-04-28T00:00:00Z');
insert into public.positions (id, revision_id, topic_id, title, short_summary, steelman, status, generated_by, review_status, sort_order) values
  ('sm_pos_a', 'sm_rev_001', 'topic_smartphones_schools', 'Yes — ban them bell-to-bell', 'Remove smartphones for the whole school day to protect attention, learning outcomes, and an equal classroom.', 'Classrooms exist to direct scarce attention toward learning, and smartphones are engineered to pull that attention away. Students receive a large share of their daily notifications during school hours, and even a silent phone within reach competes with instruction. Where schools have removed phones, researchers have found measurable test-score gains concentrated among the students who were already struggling, so a clear ban narrows gaps rather than widening them. A bell-to-bell rule is also the only version staff can enforce evenly, because it removes case-by-case negotiation from every lesson. Many teachers and parents additionally value a school day free of social media pressure, even though the direct wellbeing evidence is still contested. The ban asks for one act of restraint at the school gate instead of hundreds of small ones across the day.', 'published', 'human', 'unreviewed', 1),
  ('sm_pos_b', 'sm_rev_001', 'topic_smartphones_schools', 'No — teach managed use instead', 'Keep phones at school and teach deliberate, managed use instead of imposing a blanket ban.', 'Smartphones are the infrastructure of modern life, and school is where young people should learn to use them deliberately rather than simply have them locked away. The best direct evidence undercuts the strongest case for bans: restrictive school policies have not been shown to improve wellbeing or to reduce how much adolescents use phones overall, because most use happens outside school hours. Blanket bans also carry real costs, cutting the direct line between parents and children and turning teachers into device police in daily confiscation conflicts. A managed-use approach makes the phone an object of explicit teaching: when to silence it, how notification design works against you, and when it is a legitimate tool for learning. Students who experience only prohibition graduate with no practice at self-regulation at exactly the moment the external rules disappear.', 'published', 'human', 'unreviewed', 2),
  ('sm_pos_c', 'sm_rev_001', 'topic_smartphones_schools', 'Restrict in class, allow between lessons', 'Require phones to be away and silent during lessons while allowing limited use between them.', 'Lesson time is the scarcest resource a school has, and the evidence that phones erode it is strong enough to act on, while the evidence that all-day bans deliver broader wellbeing benefits is much weaker. A middle policy follows that asymmetry: phones are away and silent during every lesson and available during breaks and passing time. This protects instruction where distraction does its damage, keeps students reachable by their families, and lets them practice putting the phone away as a habit rather than experiencing it only as confiscation. A rule students see as proportionate is also more likely to earn the broad voluntary compliance that every phone policy ultimately depends on. The position accepts a harder enforcement boundary than a blanket ban in exchange for preserving the parts of connectivity that have genuine value.', 'published', 'human', 'unreviewed', 3);
insert into public.claims (id, revision_id, topic_id, text, claim_type, generated_by, review_status, sort_order) values
  ('sm_c1', 'sm_rev_001', 'topic_smartphones_schools', 'Smartphones and their notifications draw student attention away from classroom instruction.', array['factual', 'causal']::text[], 'human', 'unreviewed', 1),
  ('sm_c2', 'sm_rev_001', 'topic_smartphones_schools', 'Banning mobile phones in schools can raise student test scores, with the largest gains for low-achieving students.', array['causal']::text[], 'human', 'unreviewed', 2),
  ('sm_c3', 'sm_rev_001', 'topic_smartphones_schools', 'Banning phones during the school day improves adolescent mental wellbeing.', array['causal', 'predictive']::text[], 'human', 'unreviewed', 3),
  ('sm_c4', 'sm_rev_001', 'topic_smartphones_schools', 'Restrictive school phone policies on their own do not reduce adolescents'' overall daily phone and social media time.', array['factual', 'causal']::text[], 'human', 'unreviewed', 4),
  ('sm_c5', 'sm_rev_001', 'topic_smartphones_schools', 'Many students use their phones during the school day even where school policies restrict use.', array['factual']::text[], 'human', 'unreviewed', 5),
  ('sm_c6', 'sm_rev_001', 'topic_smartphones_schools', 'The benefits of a school phone policy depend on clear rules and consistent whole-school enforcement.', array['causal']::text[], 'human', 'unreviewed', 6);
insert into public.debate_arguments (id, revision_id, position_id, direction, summary, claim_ids, generated_by, review_status, sort_order) values
  ('sm_arg_a1', 'sm_rev_001', 'sm_pos_a', 'supports', 'Phones and their notifications pull student attention away from instruction across the school day.', array['sm_c1']::text[], 'human', 'unreviewed', 1),
  ('sm_arg_a2', 'sm_rev_001', 'sm_pos_a', 'supports', 'Banning phones is followed by test-score gains concentrated among the lowest-achieving students, narrowing classroom gaps.', array['sm_c2']::text[], 'human', 'unreviewed', 2),
  ('sm_arg_a3', 'sm_rev_001', 'sm_pos_a', 'qualifies', 'The mental health rationale is plausible but contested, so the ban''s core case rests on attention and learning.', array['sm_c3']::text[], 'human', 'unreviewed', 3),
  ('sm_arg_b1', 'sm_rev_001', 'sm_pos_b', 'supports', 'Restrictive school policies do not reduce overall phone or social media time, which is what actually tracks worse outcomes.', array['sm_c4']::text[], 'human', 'unreviewed', 4),
  ('sm_arg_b2', 'sm_rev_001', 'sm_pos_b', 'supports', 'Bans are leaky and costly to police, since many students use phones during school regardless of the rules.', array['sm_c5']::text[], 'human', 'unreviewed', 5),
  ('sm_arg_b3', 'sm_rev_001', 'sm_pos_b', 'qualifies', 'The wellbeing argument for bans is not borne out by the most direct comparison of restrictive and permissive schools.', array['sm_c3']::text[], 'human', 'unreviewed', 6),
  ('sm_arg_c1', 'sm_rev_001', 'sm_pos_c', 'supports', 'In-class distraction is the clearest, best-documented harm, so the rule should target lesson time directly.', array['sm_c1']::text[], 'human', 'unreviewed', 7),
  ('sm_arg_c2', 'sm_rev_001', 'sm_pos_c', 'supports', 'A lesson-time restriction pursues the documented learning gains while keeping students reachable between lessons.', array['sm_c2']::text[], 'human', 'unreviewed', 8),
  ('sm_arg_c3', 'sm_rev_001', 'sm_pos_c', 'qualifies', 'A conditional rule works only if it is bright-line and consistently enforced, because students use phones even under restrictions.', array['sm_c5', 'sm_c6']::text[], 'human', 'unreviewed', 9);
insert into public.sources (id, revision_id, topic_id, url, title, publisher, source_type, retrieval_status, retrieved_at, quality_notes, content_hash, sort_order) values
  ('sm_s1', 'sm_rev_001', 'topic_smartphones_schools', 'https://www.unesco.org/gem-report/en/publication/technology', 'Global Education Monitoring Report 2023 — Technology in education: A tool on whose terms?', 'UNESCO', 'report', 'found', '2026-04-28', 'Flagship UN report with a broad evidence synthesis; it openly advocates limiting smartphone use in schools, so its framing leans pro-restriction. Strong for international policy context; many of the studies it cites are correlational.', null, 1),
  ('sm_s2', 'sm_rev_001', 'topic_smartphones_schools', 'https://cep.lse.ac.uk/pubs/download/dp1350.pdf', 'Ill Communication: Technology, Distraction and Student Performance (CEP Discussion Paper No 1350)', 'Centre for Economic Performance, LSE', 'paper', 'found', '2026-04-28', 'Widely cited quasi-experimental study (difference-in-differences across 91 English schools) by Beland and Murphy. Strong design for test-score effects, but the data predate 2013 and may not transfer to today''s phones and apps.', null, 2),
  ('sm_s3', 'sm_rev_001', 'topic_smartphones_schools', 'https://www.gov.uk/government/publications/mobile-phones-in-schools/mobile-phones-in-schools', 'Mobile phones in schools', 'UK Department for Education', 'report', 'found', '2026-08-30', 'Official statutory guidance updated 29 June 2026. Good for what the UK Department for Education requires and why; it is a primary policy source, not an impact evaluation.', null, 3),
  ('sm_s4', 'sm_rev_001', 'topic_smartphones_schools', 'https://doi.org/10.1016/j.lanepe.2025.101211', 'School phone policies and their association with mental wellbeing, phone use, and social media use (SMART Schools): a cross-sectional observational study', 'The Lancet Regional Health - Europe', 'paper', 'found', '2026-04-28', 'Peer-reviewed University of Birmingham study of around 1,200 students in 30 English schools, the most direct comparison of restrictive and permissive policies to date. Cross-sectional design cannot establish causation, and it compares existing policies rather than evaluating a newly introduced ban.', null, 4),
  ('sm_s5', 'sm_rev_001', 'topic_smartphones_schools', 'https://www.commonsensemedia.org/sites/default/files/research/report/2023-cs-smartphone-research-report_final-for-web.pdf', 'Constant Companion: A Week in the Life of a Young Person''s Smartphone Use', 'Common Sense Media', 'report', 'found', '2026-08-30', 'Versioned primary report using passive tracking of about 200 US 11- to 17-year-olds (Android only). Unusually direct usage data, including school-day use, but the sample is small and nonrepresentative, and the organization advocates for children''s media health.', 'sha256:ba827858732c6baf782ebb5fd6ba30749143750990597fee022222b6af97adc6', 5),
  ('sm_s6', 'sm_rev_001', 'topic_smartphones_schools', 'https://www.rijksoverheid.nl/actueel/nieuws/2024/07/12/ocw-onderzoek-leerlingen-socialer-en-geconcentreerder-door-mobieltjesafspraak', 'OCW-onderzoek: leerlingen socialer en geconcentreerder door mobieltjesafspraak', 'Government of the Netherlands (Rijksoverheid)', 'article', 'found', '2026-04-28', 'Official Dutch government news item (in Dutch) on the education ministry''s survey of nearly 600 secondary schools after the national classroom phone ban; staff report students are more focused and more social. Useful for reported effects at national scale, but it is based on staff perceptions and is the government reporting on its own policy.', null, 6);
insert into public.source_excerpts (id, revision_id, source_id, text, locator, extracted_by) values
  ('sm_ex_ev_c1_s5', 'sm_rev_001', 'sm_s5', '97% of participants used their phones, for a median of 43 minutes', 'Constant Companion, p. 5 (PDF p. 11), Key Finding 2', 'human'),
  ('sm_ex_ev_c3_s4', 'sm_rev_001', 'sm_s4', 'There is no evidence that restrictive school policies are associated with overall phone and social media use or better mental wellbeing in adolescents.', 'Abstract, Interpretation; PMID 40213498', 'human'),
  ('sm_ex_ev_c4_s4', 'sm_rev_001', 'sm_s4', 'there was no evidence for differences when comparing usage time on weekdays or weekends', 'Abstract, Findings; PMID 40213498', 'human'),
  ('sm_ex_ev_c5_s5', 'sm_rev_001', 'sm_s5', 'policies about phone use in schools vary—sometimes even from classroom to classroom—and aren''t always enforced', 'Constant Companion, executive summary, PDF p. 4', 'human'),
  ('sm_ex_ev_c6_s3', 'sm_rev_001', 'sm_s3', 'All staff should consistently enforce the school''s policy on the use of mobile phones.', 'Mobile phones in schools, section ''The role of staff''', 'human');
insert into public.evidence_links (id, revision_id, claim_id, source_id, source_excerpt_id, label, rationale, confidence, review_status, sort_order) values
  ('sm_ev_c1_s1', 'sm_rev_001', 'sm_c1', 'sm_s1', null, 'supports_claim', 'The GEM Report cites research from 14 countries finding that mere proximity to a mobile device distracts students and harms learning, which grounds its call to restrict smartphones in schools.', 0.75, 'unreviewed', 1),
  ('sm_ev_c1_s5', 'sm_rev_001', 'sm_c1', 'sm_s5', 'sm_ex_ev_c1_s5', 'supports_claim', 'Tracking data showed participants received roughly a quarter of their daily notifications during school hours and used phones a median of 43 minutes during the school day, documenting the volume of interruption rather than measuring attention loss directly.', 0.7, 'unreviewed', 2),
  ('sm_ev_c2_s2', 'sm_rev_001', 'sm_c2', 'sm_s2', null, 'supports_claim', 'Beland and Murphy found high-stakes exam scores rose by 6.4% of a standard deviation after English schools banned phones, with gains concentrated among the lowest-achieving students.', 0.8, 'unreviewed', 3),
  ('sm_ev_c2_s1', 'sm_rev_001', 'sm_c2', 'sm_s1', null, 'partially_supports_claim', 'UNESCO cites evidence that removing smartphones from schools in some countries improved learning, while noting that rigorous evidence on technology''s effects in education is scarce overall.', 0.65, 'unreviewed', 4),
  ('sm_ev_c3_s4', 'sm_rev_001', 'sm_c3', 'sm_s4', 'sm_ex_ev_c3_s4', 'contradicts_claim', 'The SMART Schools study found no significant difference in mental wellbeing, anxiety, or depression between students at schools with restrictive phone policies and those at permissive ones.', 0.8, 'unreviewed', 5),
  ('sm_ev_c3_s1', 'sm_rev_001', 'sm_c3', 'sm_s1', null, 'unclear', 'UNESCO recommends restricting smartphones in schools partly on wellbeing grounds, but the report offers little direct evidence that school bans themselves improve wellbeing.', 0.55, 'unreviewed', 6),
  ('sm_ev_c4_s4', 'sm_rev_001', 'sm_c4', 'sm_s4', 'sm_ex_ev_c4_s4', 'supports_claim', 'Restrictive school policies were not associated with lower overall phone or social media time among adolescents; higher overall time, wherever it occurred, was what tracked worse wellbeing, sleep, and attainment.', 0.8, 'unreviewed', 7),
  ('sm_ev_c5_s5', 'sm_rev_001', 'sm_c5', 'sm_s5', 'sm_ex_ev_c5_s5', 'supports_claim', 'Nearly all tracked participants used their phones during school hours, with a median of 43 minutes per school day, and the report notes that school rules vary classroom to classroom and are not consistently enforced.', 0.7, 'unreviewed', 8),
  ('sm_ev_c6_s6', 'sm_rev_001', 'sm_c6', 'sm_s6', null, 'partially_supports_claim', 'Dutch schools reported better focus and a better social climate after a clear national rule that each school turned into concrete local policy, though the survey has no comparison group of weakly enforced policies.', 0.65, 'unreviewed', 9),
  ('sm_ev_c6_s3', 'sm_rev_001', 'sm_c6', 'sm_s3', 'sm_ex_ev_c6_s3', 'partially_supports_claim', 'The DfE guidance asserts that consistent whole-school approaches are the most effective way to manage phones, but as policy guidance it relies on examples rather than systematic evaluation.', 0.6, 'unreviewed', 10);
insert into public.debate_values (id, revision_id, topic_id, name, description, tension_with, sort_order) values
  ('sm_val_attention', 'sm_rev_001', 'topic_smartphones_schools', 'Focused Learning', 'Classroom time is scarce, and instruction deserves protection from engineered competition for student attention.', array['constant connectivity', 'student discretion during lessons']::text[], 1),
  ('sm_val_equity', 'sm_rev_001', 'topic_smartphones_schools', 'Equal Classroom', 'School rules should prevent device habits and distractions from widening achievement gaps between students.', array['case-by-case exceptions', 'family discretion over devices']::text[], 2),
  ('sm_val_autonomy', 'sm_rev_001', 'topic_smartphones_schools', 'Autonomy and Digital Literacy', 'Students should graduate able to manage their own technology use rather than only ever having it managed for them.', array['uniform blanket bans', 'short-term classroom order']::text[], 3),
  ('sm_val_reachability', 'sm_rev_001', 'topic_smartphones_schools', 'Family Reachability', 'Parents and students place real weight on being able to reach each other directly during the school day.', array['bell-to-bell bans', 'routing all contact through the school office']::text[], 4);
insert into public.value_positions (value_id, position_id) values
  ('sm_val_attention', 'sm_pos_a'),
  ('sm_val_attention', 'sm_pos_c'),
  ('sm_val_equity', 'sm_pos_a'),
  ('sm_val_autonomy', 'sm_pos_b'),
  ('sm_val_autonomy', 'sm_pos_c'),
  ('sm_val_reachability', 'sm_pos_b'),
  ('sm_val_reachability', 'sm_pos_c');
insert into public.tradeoffs (id, revision_id, topic_id, position_id, gain, cost, risk, review_status) values
  ('sm_to_a', 'sm_rev_001', 'topic_smartphones_schools', 'sm_pos_a', 'Protected attention in every lesson, documented test-score gains for struggling students, and one less social pressure inside school.', 'Families lose direct contact during the day and staff take on gate-to-gate enforcement work.', 'Use may move out of sight, and confiscation disputes could consume the time and goodwill the ban was meant to save.', 'unreviewed'),
  ('sm_to_b', 'sm_rev_001', 'topic_smartphones_schools', 'sm_pos_b', 'Preserves family contact and gives students supervised practice at self-regulation before the external rules disappear.', 'Keeps a documented distraction within reach during lessons and asks teachers to police nuance instead of a bright line.', 'If the teaching component is weak, managed use can collapse into de facto unrestricted use.', 'unreviewed'),
  ('sm_to_c', 'sm_rev_001', 'topic_smartphones_schools', 'sm_pos_c', 'Protects instruction time while keeping students reachable and building the habit of putting the phone away.', 'A conditional rule is harder to enforce consistently than a blanket ban and invites boundary-testing at every bell.', 'Between-lesson use can spill into class time, delivering neither the focus of a ban nor the autonomy of managed use.', 'unreviewed');
insert into public.audit_events (topic_id, revision_id, actor_type, actor_id, event_type, input_object_ids, output_object_ids, summary, created_at) values
  ('topic_smartphones_schools', 'sm_rev_001', 'admin', null, 'topic_created', '{}', '{}', 'Topic created from the smartphones-in-schools seed packet.', '2026-04-30T09:00:00Z'),
  ('topic_smartphones_schools', 'sm_rev_001', 'system', 'retriever_v0', 'source_added', '{}', '{}', '6 sources added and retrieved successfully (status: found): UNESCO GEM Report, CEP (LSE), UK DfE, The Lancet Regional Health - Europe, Common Sense Media, Government of the Netherlands.', '2026-04-30T09:05:00Z'),
  ('topic_smartphones_schools', 'sm_rev_001', 'admin', null, 'claim_extracted', '{}', '{}', '6 atomic claims (C1–C6) extracted manually from the seed packet.', '2026-04-30T09:20:00Z'),
  ('topic_smartphones_schools', 'sm_rev_001', 'admin', null, 'evidence_labeled', '{}', '{}', '10 evidence links labeled (claim–source alignment), including 1 contradicting and 1 unclear link on the wellbeing claim. All marked unreviewed.', '2026-04-30T09:40:00Z'),
  ('topic_smartphones_schools', 'sm_rev_001', 'admin', null, 'revision_published', '{}', '{}', '3 positions structured with steelmans, values, and trade-offs; revision 1 published. Open tasks: longitudinal wellbeing evidence and an independent evaluation of the Dutch ban.', '2026-04-30T10:15:00Z');
insert into public.topics (id, slug, title, question, summary, status, created_by, created_at) values
  ('topic_nuclear_power', 'nuclear-power', 'Nuclear Power Expansion', 'Should nuclear power be expanded to fight climate change?', 'A policy debate about whether building new nuclear plants should be part of climate strategy — weighing firm low-carbon power, land use, and safety per unit of energy against cost overruns, deployment speed, waste, and the cheaper alternative of renewables plus storage.', 'draft', null, '2026-05-19T00:00:00Z');
insert into public.debate_revisions (id, topic_id, revision_number, status, review_status, generated_by, created_by, created_at) values
  ('nu_rev_001', 'topic_nuclear_power', 1, 'draft', 'unreviewed', 'human', null, '2026-05-19T00:00:00Z');
insert into public.positions (id, revision_id, topic_id, title, short_summary, steelman, status, generated_by, review_status, sort_order) values
  ('nu_pos_a', 'nu_rev_001', 'topic_nuclear_power', 'Yes — expand it as firm low-carbon power', 'Build new nuclear capacity because deep decarbonization needs firm low-carbon power alongside renewables.', 'Decarbonizing the whole economy means electrifying transport, heat, and industry while replacing fossil generation, and most credible modeled pathways for doing so include more nuclear power. Wind and solar are essential but variable, and grids still need firm low-carbon capacity that works through still weeks and dark winters. Nuclear provides that today at scale, from a land footprint far smaller than the equivalent renewable output. Measured per unit of electricity generated, its safety record over six decades is comparable to wind and solar and vastly better than the fossil fuels it displaces. Recent Western cost overruns reflect atrophied supply chains and first-of-a-kind projects rather than physical limits, and countries that build standardized designs in series have done much better. Excluding a proven firm low-carbon source makes net zero harder, slower, and more expensive than it needs to be.', 'published', 'human', 'unreviewed', 1),
  ('nu_pos_b', 'nu_rev_001', 'topic_nuclear_power', 'No — renewables are faster and cheaper', 'Direct climate capital to solar, wind, and storage, which cut emissions faster and at lower cost than new nuclear builds.', 'Climate policy is a race measured in cost per tonne of carbon avoided and in years, and new nuclear currently performs poorly on both. Recent Western projects have run years late and billions over budget, while solar, wind, and storage costs have fallen steeply and continue to fall. Every dollar and decade committed to a slow nuclear build is a dollar and decade not spent on options that decarbonize sooner, so the opportunity cost of capital is itself a climate cost. Nuclear also carries burdens renewables do not: long-lived waste with no operating permanent disposal in most countries, and fuel-cycle technologies that raise proliferation concerns. Grid flexibility, transmission, demand response, and storage are more credible complements to cheap renewables than a technology whose costs rose while everything around it got cheaper.', 'published', 'human', 'unreviewed', 2),
  ('nu_pos_c', 'nu_rev_001', 'topic_nuclear_power', 'Keep existing plants, stay agnostic on new builds', 'Extend the operating lives of existing reactors and judge any new build case-by-case on cost and timeline.', 'The cheapest and fastest firm low-carbon capacity is the nuclear fleet that already exists, and closing healthy reactors early has repeatedly led to fossil generation filling the gap. License extensions and uprates deliver low-carbon power at a fraction of the cost of any new construction, nuclear or otherwise. New builds are a different bet entirely: their record on cost and schedule is mixed at best and varies enormously by country, design maturity, and supply chain. The sensible policy is therefore asymmetric — defend existing plants vigorously, and approve new projects only when a specific proposal beats the alternatives on cost, timeline, and risk. This keeps the nuclear option open without writing blank checks, and lets the next few projects generate the evidence the debate currently lacks.', 'published', 'human', 'unreviewed', 3);
insert into public.claims (id, revision_id, topic_id, text, claim_type, generated_by, review_status, sort_order) values
  ('nu_c1', 'nu_rev_001', 'topic_nuclear_power', 'Most modeled pathways that limit warming to 1.5–2°C include an increase in global nuclear generation.', array['factual', 'predictive']::text[], 'human', 'unreviewed', 1),
  ('nu_c2', 'nu_rev_001', 'topic_nuclear_power', 'Measured in deaths per unit of electricity generated, nuclear power is far safer than fossil fuels and comparable to wind and solar.', array['factual']::text[], 'human', 'unreviewed', 2),
  ('nu_c3', 'nu_rev_001', 'topic_nuclear_power', 'Including firm low-carbon generation such as nuclear can lower the total cost of deeply decarbonized power systems.', array['causal']::text[], 'human', 'unreviewed', 3),
  ('nu_c4', 'nu_rev_001', 'topic_nuclear_power', 'On current levelized cost estimates, electricity from new nuclear plants costs more than utility-scale solar and onshore wind.', array['factual']::text[], 'human', 'unreviewed', 4),
  ('nu_c5', 'nu_rev_001', 'topic_nuclear_power', 'Extending the operating lives of existing nuclear plants is among the cheapest sources of low-carbon electricity.', array['factual']::text[], 'human', 'unreviewed', 5),
  ('nu_c6', 'nu_rev_001', 'topic_nuclear_power', 'Nuclear capacity can be expanded quickly enough to contribute substantially to 2050 climate targets.', array['predictive']::text[], 'human', 'unreviewed', 6),
  ('nu_c7', 'nu_rev_001', 'topic_nuclear_power', 'Renewables plus storage are a fast-growing share of new capacity, and their costs have fallen steeply over the last decade.', array['factual']::text[], 'human', 'unreviewed', 7),
  ('nu_c8', 'nu_rev_001', 'topic_nuclear_power', 'Recent Western nuclear cost overruns generalize to future builds rather than reflecting first-of-a-kind effects.', array['predictive', 'causal']::text[], 'human', 'unreviewed', 8);
insert into public.debate_arguments (id, revision_id, position_id, direction, summary, claim_ids, generated_by, review_status, sort_order) values
  ('nu_arg_a1', 'nu_rev_001', 'nu_pos_a', 'supports', 'Most credible net-zero pathways include more nuclear, because grids need firm low-carbon power alongside variable renewables.', array['nu_c1', 'nu_c3']::text[], 'human', 'unreviewed', 1),
  ('nu_arg_a2', 'nu_rev_001', 'nu_pos_a', 'supports', 'Per unit of electricity generated, nuclear''s safety record is comparable to wind and solar and far better than fossil fuels.', array['nu_c2']::text[], 'human', 'unreviewed', 2),
  ('nu_arg_a3', 'nu_rev_001', 'nu_pos_a', 'qualifies', 'Whether new builds can scale fast enough is contested, so expansion should favor standardized designs built in series — the same series-build logic that makes extending today''s fleet the cheap path.', array['nu_c6', 'nu_c5']::text[], 'human', 'unreviewed', 3),
  ('nu_arg_b1', 'nu_rev_001', 'nu_pos_b', 'supports', 'On current cost estimates, new nuclear electricity is substantially more expensive than utility-scale solar and onshore wind.', array['nu_c4']::text[], 'human', 'unreviewed', 4),
  ('nu_arg_b2', 'nu_rev_001', 'nu_pos_b', 'supports', 'Slow, over-budget builds carry an opportunity cost: the same capital deployed in renewables and storage cuts emissions sooner.', array['nu_c4', 'nu_c6']::text[], 'human', 'unreviewed', 5),
  ('nu_arg_b3', 'nu_rev_001', 'nu_pos_b', 'qualifies', 'Even granting firm power its system value, that value must be weighed against waste and proliferation burdens unique to nuclear.', array['nu_c3']::text[], 'human', 'unreviewed', 6),
  ('nu_arg_b4', 'nu_rev_001', 'nu_pos_b', 'supports', 'Renewables plus storage are a fast-growing, ever-cheaper share of new capacity, while recent nuclear overruns look like the rule for future builds rather than a one-off.', array['nu_c7', 'nu_c8']::text[], 'human', 'unreviewed', 7),
  ('nu_arg_c1', 'nu_rev_001', 'nu_pos_c', 'supports', 'Extending existing reactors preserves large amounts of firm low-carbon capacity at low cost.', array['nu_c5']::text[], 'human', 'unreviewed', 8),
  ('nu_arg_c2', 'nu_rev_001', 'nu_pos_c', 'supports', 'Firm low-carbon capacity has real system value, and the existing fleet delivers it without new-build cost and schedule risk.', array['nu_c3', 'nu_c5']::text[], 'human', 'unreviewed', 9),
  ('nu_arg_c3', 'nu_rev_001', 'nu_pos_c', 'qualifies', 'The new-build record is mixed and varies by country and design, so proposals deserve case-by-case judgment rather than blanket approval or rejection.', array['nu_c4', 'nu_c6']::text[], 'human', 'unreviewed', 10),
  ('nu_arg_c4', 'nu_rev_001', 'nu_pos_c', 'qualifies', 'Cheap, fast-growing renewables plus storage are real and welcome, but they sharpen rather than settle the case-by-case test any new reactor must pass.', array['nu_c7']::text[], 'human', 'unreviewed', 11);
insert into public.sources (id, revision_id, topic_id, url, title, publisher, source_type, retrieval_status, retrieved_at, quality_notes, content_hash, sort_order) values
  ('nu_s1', 'nu_rev_001', 'topic_nuclear_power', 'https://www.ipcc.ch/report/ar6/wg3/', 'Climate Change 2022: Mitigation of Climate Change (AR6 Working Group III)', 'Intergovernmental Panel on Climate Change', 'report', 'found', '2026-05-19', 'Consensus assessment by the UN climate science body; the strongest available source for what modeled mitigation pathways assume. Scenario ranges are wide and aggregate many models, so single-number citations need care.', null, 1),
  ('nu_s2', 'nu_rev_001', 'topic_nuclear_power', 'https://www.iea.org/reports/net-zero-by-2050', 'Net Zero by 2050: A Roadmap for the Global Energy Sector', 'International Energy Agency', 'report', 'found', '2026-05-19', 'Influential intergovernmental modeling exercise. Its nuclear figures are scenario outputs conditional on policy, not forecasts, and the IEA has historically underestimated renewables growth.', null, 2),
  ('nu_s3', 'nu_rev_001', 'topic_nuclear_power', 'https://www.lazard.com/media/kcfconhf/lazards-lcoeplus_vf.pdf', 'Levelized Cost of Energy+ — July 2026 (LCOE v19.0 / LCOS v11.0)', 'Lazard', 'report', 'found', '2026-08-30', 'Exact July 2026 LCOE+ report (LCOE v19.0 / LCOS v11.0), a widely cited investment-bank benchmark for U.S. generation costs. LCOE excludes system integration and firming costs, which understates the value of dispatchable plants, and its new-nuclear estimates rest on very few recent U.S. data points.', null, 3),
  ('nu_s4', 'nu_rev_001', 'topic_nuclear_power', 'https://www.worldnuclearreport.org/IMG/pdf/wnisr2025-v2.pdf', 'World Nuclear Industry Status Report 2025 (v2)', 'Mycle Schneider Consulting', 'report', 'found', '2026-08-30', 'Versioned 2025 v2 report with detailed annual data on reactor construction starts, delays, and costs. Editorially nuclear-skeptic: its trend data is widely used, but its framing consistently argues against new nuclear.', 'sha256:c07bb64e0877b640ac81e3b3c6faf18e7715b90595b95e4ee08ebbd85bae8688', 4),
  ('nu_s5', 'nu_rev_001', 'topic_nuclear_power', 'https://energy.mit.edu/wp-content/uploads/2018/09/The-Future-of-Nuclear-Energy-in-a-Carbon-Constrained-World.pdf', 'The Future of Nuclear Energy in a Carbon-Constrained World', 'MIT Energy Initiative', 'report', 'found', '2026-08-30', 'Exact 2018 MIT report with system-cost modeling. Pro-nuclear-policy leaning in its recommendations, though candid about the industry''s cost failures; its cost data predates the most recent projects.', 'sha256:1ee81638b8d14c6c574056ac4ad0361b85c41ee35068f3748c98a29bf28455b3', 5),
  ('nu_s6', 'nu_rev_001', 'topic_nuclear_power', 'https://ourworldindata.org/safest-sources-of-energy', 'What are the safest and cleanest sources of energy?', 'Our World in Data', 'article', 'found', '2026-05-19', 'Accessible synthesis of peer-reviewed mortality estimates per unit of energy. Good for orders of magnitude; the underlying death-rate estimates carry real uncertainty, especially for chronic air-pollution impacts.', null, 6);
insert into public.source_excerpts (id, revision_id, source_id, text, locator, extracted_by) values
  ('nu_ex_ev_c3_s5', 'nu_rev_001', 'nu_s5', 'Without that contribution, the cost of achieving deep decarbonization targets increases significantly.', 'MIT report, Executive Summary, p. xiii', 'human'),
  ('nu_ex_ev_c4_s3', 'nu_rev_001', 'nu_s3', 'Unsubsidized renewable energy remains the most cost-competitive form of new-build generation on an LCOE basis.', 'Lazard LCOE v19.0, Executive Summary, p. 3', 'human'),
  ('nu_ex_ev_c6_s4', 'nu_rev_001', 'nu_s4', 'All reactors under construction in at least six of the 11 countries hosting building sites have experienced, often year-long, delays.', 'WNISR 2025 v2, Construction Times, p. 24', 'human');
insert into public.evidence_links (id, revision_id, claim_id, source_id, source_excerpt_id, label, rationale, confidence, review_status, sort_order) values
  ('nu_ev_c1_s1', 'nu_rev_001', 'nu_c1', 'nu_s1', null, 'supports_claim', 'AR6 mitigation pathways limiting warming to around 1.5–2°C show nuclear generation increasing in most scenarios, though the range across models is wide.', 0.8, 'unreviewed', 1),
  ('nu_ev_c1_s2', 'nu_rev_001', 'nu_c1', 'nu_s2', null, 'supports_claim', 'The IEA net-zero scenario shows global nuclear generation roughly doubling between 2020 and 2050, alongside much larger growth in renewables.', 0.8, 'unreviewed', 2),
  ('nu_ev_c2_s6', 'nu_rev_001', 'nu_c2', 'nu_s6', null, 'supports_claim', 'Our World in Data''s synthesis of death rates per terawatt-hour places nuclear close to wind and solar and orders of magnitude below coal, oil, and gas.', 0.85, 'unreviewed', 3),
  ('nu_ev_c3_s5', 'nu_rev_001', 'nu_c3', 'nu_s5', 'nu_ex_ev_c3_s5', 'supports_claim', 'The MIT study''s system modeling finds that excluding firm low-carbon options such as nuclear substantially raises the average cost of deep decarbonization.', 0.8, 'unreviewed', 4),
  ('nu_ev_c3_s2', 'nu_rev_001', 'nu_c3', 'nu_s2', null, 'partially_supports_claim', 'The IEA pathway relies on a portfolio of dispatchable low-emissions sources alongside renewables, but does not single out nuclear as indispensable.', 0.6, 'unreviewed', 5),
  ('nu_ev_c4_s3', 'nu_rev_001', 'nu_c4', 'nu_s3', 'nu_ex_ev_c4_s3', 'supports_claim', 'Lazard''s levelized cost analysis places new nuclear well above utility-scale solar and onshore wind per megawatt-hour, even across its wide estimate ranges.', 0.85, 'unreviewed', 6),
  ('nu_ev_c4_s5', 'nu_rev_001', 'nu_c4', 'nu_s5', null, 'partially_supports_claim', 'The MIT study concedes that recent Western new builds are expensive, while arguing that levelized cost alone understates the value of firm capacity.', 0.65, 'unreviewed', 7),
  ('nu_ev_c5_s2', 'nu_rev_001', 'nu_c5', 'nu_s2', null, 'supports_claim', 'The IEA roadmap treats extended operation of existing reactors as a low-cost component of its net-zero pathway.', 0.7, 'unreviewed', 8),
  ('nu_ev_c5_s3', 'nu_rev_001', 'nu_c5', 'nu_s3', null, 'supports_claim', 'Lazard reports the marginal cost of running fully depreciated nuclear plants as low relative to building new generation of any type.', 0.7, 'unreviewed', 9),
  ('nu_ev_c6_s4', 'nu_rev_001', 'nu_c6', 'nu_s4', 'nu_ex_ev_c6_s4', 'contradicts_claim', 'WNISR documents nuclear''s shrinking share of global generation and roughly decade-long average project timelines, concluding the technology scales too slowly to matter for 2050 targets.', 0.75, 'unreviewed', 10),
  ('nu_ev_c6_s2', 'nu_rev_001', 'nu_c6', 'nu_s2', null, 'partially_supports_claim', 'The IEA scenario shows nuclear roughly doubling by 2050, but as a policy-contingent scenario outcome rather than evidence of current deployment rates.', 0.6, 'unreviewed', 11),
  ('nu_ev_c4_s2', 'nu_rev_001', 'nu_c4', 'nu_s2', null, 'unclear', 'The IEA roadmap''s system-value framing implies LCOE alone understates firm capacity, leaving the bare cost comparison unsettled once integration costs are included.', 0.5, 'unreviewed', 12),
  ('nu_ev_c7_s4', 'nu_rev_001', 'nu_c7', 'nu_s4', null, 'supports_claim', 'WNISR''s annual data show renewables capturing the overwhelming majority of new capacity additions, with solar and wind growing far faster than nuclear over the past decade.', 0.8, 'unreviewed', 13),
  ('nu_ev_c7_s2', 'nu_rev_001', 'nu_c7', 'nu_s2', null, 'partially_supports_claim', 'The IEA roadmap projects renewables and storage as the dominant share of new investment, consistent with steep recent cost declines, though its specific figures are scenario outputs rather than observed prices.', 0.65, 'unreviewed', 14),
  ('nu_ev_c8_s5', 'nu_rev_001', 'nu_c8', 'nu_s5', null, 'contradicts_claim', 'The MIT study attributes recent Western overruns largely to first-of-a-kind effects, atrophied supply chains, and lost serial-build experience, arguing they need not generalize to standardized future builds.', 0.75, 'unreviewed', 15),
  ('nu_ev_c8_s4', 'nu_rev_001', 'nu_c8', 'nu_s4', null, 'supports_claim', 'WNISR''s construction record shows persistent, repeated cost and schedule overruns across countries and decades, which it reads as a structural feature of new nuclear rather than a transient first-of-a-kind problem.', 0.7, 'unreviewed', 16);
insert into public.debate_values (id, revision_id, topic_id, name, description, tension_with, sort_order) values
  ('nu_val_climate', 'nu_rev_001', 'topic_nuclear_power', 'Climate Urgency', 'Cutting emissions fast enough to meet mid-century targets matters more than loyalty to any particular technology.', array['local siting concerns', 'short-term electricity prices']::text[], 1),
  ('nu_val_reliability', 'nu_rev_001', 'topic_nuclear_power', 'Grid Reliability', 'A decarbonized grid must deliver power on demand through still weeks and dark winters, not only when wind and sun cooperate.', array['least-cost procurement', 'rapid variable-renewables build-out']::text[], 2),
  ('nu_val_cost', 'nu_rev_001', 'topic_nuclear_power', 'Cost Discipline', 'Public and private capital should buy the most emissions reduction per dollar, as quickly as possible.', array['technology diversity', 'long-horizon industrial planning', 'option value of firm capacity']::text[], 3),
  ('nu_val_stewardship', 'nu_rev_001', 'topic_nuclear_power', 'Intergenerational Stewardship', 'Energy choices should not hand long-lived waste, accident, or weapons-proliferation risks to future generations.', array['near-term emissions cuts', 'energy abundance']::text[], 4);
