insert into public.tradeoffs (id, revision_id, topic_id, position_id, gain, cost, risk, review_status) values
  ('nu_to_a', 'nu_rev_001', 'topic_nuclear_power', 'nu_pos_a', 'Firm low-carbon capacity that complements renewables, with small land use and a strong safety record.', 'High upfront capital, long construction timelines, and long-lived waste to manage.', 'Repeated cost overruns could absorb capital and political will that faster options would have used better.', 'unreviewed'),
  ('nu_to_b', 'nu_rev_001', 'topic_nuclear_power', 'nu_pos_b', 'Capital flows to the cheapest and fastest-deploying low-carbon options available today.', 'Forgoes firm low-carbon capacity, leaving harder reliability problems as grids approach full decarbonization.', 'If storage and grid flexibility scale slower than hoped, decarbonization could stall at high renewable shares.', 'unreviewed'),
  ('nu_to_c', 'nu_rev_001', 'topic_nuclear_power', 'nu_pos_c', 'Preserves existing low-carbon capacity cheaply while avoiding premature bets on new construction.', 'Sends no clear industrial signal, which keeps the nuclear supply chain and workforce in decline.', 'Case-by-case ambivalence can become a de facto phase-out if no new project ever clears the bar.', 'unreviewed');
